#!/usr/bin/env python3
"""Generate ``paper/figures/generated_values.tex`` from the result artifacts.

Why
---
Every plotted number in the S&P figures used to be a literal in the figure
source. Nothing tied those literals to the artifacts, so they drifted: on
2026-10-08 the persona interval in Figure~2 still carried a lower error of
0.0573 while ``results/bootstrap_ci.json`` had been regenerated to 0.0587.
A stale error bar is invisible to every existing check.

This script makes the figures read their values from one generated file, and
``--check`` fails when the committed file disagrees with the artifacts, so the
drift becomes a CI failure instead of a figure a reader cannot trust.

Sources
-------
``results/bootstrap_ci.json``            live both-channel means + CIs, grounding deltas
``results/stability_run1_vs_run2.json``  second-run point estimates
``results/b4_baseline_zodiac_20260922.json``  grounded/ungrounded TTP counts
``results/model_quality/chrollo_calibration.json``  profiler baseline accuracy
``results/sp2027_rescue/behavior_trajectory_benchmark.json``  trajectory endpoint

Usage::

    python scripts/gen_sp_figures.py           # write the generated file
    python scripts/gen_sp_figures.py --check   # fail if stale, write nothing
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RESULTS = ROOT / "results"
OUT = ROOT / "paper" / "figures" / "generated_values.tex"

SOURCES = {
    "bootstrap": "results/bootstrap_ci.json",
    "stability": "results/stability_run1_vs_run2.json",
    "b4": "results/b4_baseline_zodiac_20260922.json",
    "chrollo": "results/model_quality/chrollo_calibration.json",
    "trajectory": "results/sp2027_rescue/behavior_trajectory_benchmark.json",
}


def load() -> dict[str, dict]:
    missing = [p for p in SOURCES.values() if not (ROOT / p).exists()]
    if missing:
        print(f"missing artifacts: {missing}", file=sys.stderr)
        raise SystemExit(2)
    return {k: json.loads((ROOT / v).read_text()) for k, v in SOURCES.items()}


def half_width(point: float, lo: float, hi: float) -> tuple[float, float]:
    return round(point - lo, 4), round(hi - point, 4)


def build() -> str:
    d = load()
    live = d["bootstrap"]["live_audited"]
    paired = d["bootstrap"]["b4_baseline"]["paired_diff_ci"]

    lines = [
        "% GENERATED by scripts/gen_sp_figures.py -- do not edit by hand.",
        "% Every plotted number in the S&P figures resolves through this file, so a",
        "% figure cannot silently disagree with the artifact it claims to show.",
        "% Regenerate:  python scripts/gen_sp_figures.py",
        "% Verify:      python scripts/gen_sp_figures.py --check",
        "% Sources:",
    ]
    lines += [f"%   {p}" for p in SOURCES.values()]
    lines.append("")

    for label in ("technique", "actor", "persona"):
        ci = live[label]["mean_ci"]
        lo_err, hi_err = half_width(ci["point"], ci["lo"], ci["hi"])
        suffix = {"technique": "Technique", "actor": "Actor", "persona": "Persona"}[label]
        lines += [
            f"\\def\\RaginLive{suffix}{{{ci['point']:.4f}}}",
            f"\\def\\RaginLive{suffix}ErrLo{{{lo_err:.4f}}}",
            f"\\def\\RaginLive{suffix}ErrHi{{{hi_err:.4f}}}",
        ]

    comp = live["composite"]["mean_ci"]
    comp_lo, comp_hi = half_width(comp["point"], comp["lo"], comp["hi"])
    lines += [
        f"\\def\\RaginLiveComposite{{{comp['point']:.4f}}}",
        f"\\def\\RaginLiveCompositeErrLo{{{comp_lo:.4f}}}",
        f"\\def\\RaginLiveCompositeErrHi{{{comp_hi:.4f}}}",
    ]

    suites = {s["suite"]: s for s in d["stability"]["suites"]}
    run_b = suites["deception"]["mean_run_b"]
    lines += [
        f"\\def\\RaginLivePersonaRunTwo{{{run_b:.4f}}}",
        f"\\def\\RaginLiveCompositeRunTwo{{{d['stability']['composite']['composite_run_b']:.4f}}}",
        f"\\def\\RaginPersonaRunDelta{{{round(run_b - suites['deception']['mean_run_a'], 3):.3f}}}",
    ]

    for macro, suite in (
        ("RaginTechDelta", "cti_technique"),
        ("RaginActorDelta", "cti_actor"),
        ("RaginPersonaNullDelta", "deception"),
        ("RaginOverallDelta", "overall"),
    ):
        ci = paired[suite]
        lines += [
            f"\\def\\{macro}{{{ci['point']:.3f}}}",
            f"\\def\\{macro}Lo{{{ci['lo']:.3f}}}",
            f"\\def\\{macro}Hi{{{ci['hi']:.3f}}}",
        ]

    lines += [
        f"\\def\\RaginGroundingTtpCount{{{d['b4']['rag']['metrics']['ttps_detected']}}}",
        f"\\def\\RaginNoGroundingTtpCount{{{d['b4']['no_rag']['metrics']['ttps_detected']}}}",
        f"\\def\\RaginRoutingBefore{{{d['chrollo']['summary']['accuracy']:.4f}}}",
        "\\def\\RaginRoutingAfter{"
        f"{d['trajectory']['arms']['skill_only']['prefix_summary']['prefixes']['all']['skill_accuracy']:.3f}}}",
        "",
    ]
    return "\n".join(lines)


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--check", action="store_true", help="fail if the committed file is stale")
    args = ap.parse_args()

    content = build()
    if args.check:
        if not OUT.exists():
            print(f"FAIL {OUT} does not exist")
            return 1
        current = OUT.read_text()
        if current != content:
            print(f"FAIL {OUT.relative_to(ROOT)} is stale; run: python scripts/gen_sp_figures.py")
            return 1
        print(f"OK   {OUT.relative_to(ROOT)} matches the artifacts")
        return 0

    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(content)
    print(f"wrote {OUT.relative_to(ROOT)} ({len(content.splitlines())} lines)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())